// Extract and detect MIME type
const items = [];

for (const item of $input.all()) {
  const binary = item.binary;
  const fileName = Object.keys(binary)[0];
  const fileData = binary[fileName];

  // Get MIME type from binary data or detect from extension
  let mimeType = fileData.mimeType || 'application/octet-stream';

  // Fallback detection based on file extension
  const ext = fileName.split('.').pop().toLowerCase();
  if (!fileData.mimeType) {
    const mimeMap = {
      'pdf': 'application/pdf',
      'doc': 'application/msword',
      'docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      'xls': 'application/vnd.ms-excel',
      'xlsx': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      'jpg': 'image/jpeg',
      'jpeg': 'image/jpeg',
      'png': 'image/png',
      'txt': 'text/plain',
      'csv': 'text/csv',
      'json': 'application/json',
      'xml': 'application/xml'
    };
    mimeType = mimeMap[ext] || mimeType;
  }

  items.push({
    json: {
      fileName: fileName,
      mimeType: mimeType,
      fileSize: fileData.fileSize || 0,
      fileExtension: ext,
      uploadTime: new Date().toISOString()
    },
    binary: binary
  });
}

return items;

// Extract detailed metadata from documents
const items = [];

for (const item of $input.all()) {
  const binary = item.binary;
  const fileName = Object.keys(binary)[0];
  const fileData = binary[fileName];
  const mimeType = item.json.mimeType;

  let metadata = {
    fileName: item.json.fileName,
    mimeType: mimeType,
    fileSize: item.json.fileSize,
    fileExtension: item.json.fileExtension,
    uploadTime: item.json.uploadTime,
    // Additional metadata
    isImage: mimeType.startsWith('image/'),
    isDocument: mimeType.includes('document') || mimeType.includes('pdf') || mimeType.includes('word'),
    isSpreadsheet: mimeType.includes('spreadsheet') || mimeType.includes('excel'),
    isText: mimeType.startsWith('text/'),
    isArchive: mimeType.includes('zip') || mimeType.includes('compressed'),
    // File size category
    sizeCategory: item.json.fileSize < 1000000 ? 'small' : 
                  item.json.fileSize < 10000000 ? 'medium' : 'large'
  };

  items.push({
    json: metadata,
    binary: binary
  });
}

return items;

// Classify documents based on metadata
const items = [];

for (const item of $input.all()) {
  const meta = item.json;
  let classification = 'other';
  let category = 'uncategorized';
  let priority = 'normal';

  // Classification logic based on MIME type and metadata
  if (meta.isDocument) {
    classification = 'document';
    category = 'office-document';

    // Subcategorize based on file type
    if (meta.mimeType.includes('pdf')) {
      category = 'pdf-document';
    } else if (meta.mimeType.includes('word')) {
      category = 'word-document';
    }
  } else if (meta.isSpreadsheet) {
    classification = 'spreadsheet';
    category = 'data-file';
  } else if (meta.isImage) {
    classification = 'image';
    category = 'media-file';

    // Check for common document scan patterns
    if (meta.fileName.toLowerCase().includes('scan') || 
        meta.fileName.toLowerCase().includes('invoice') ||
        meta.fileName.toLowerCase().includes('receipt')) {
      category = 'scanned-document';
      priority = 'high';
    }
  } else if (meta.isText) {
    classification = 'text';
    category = meta.mimeType.includes('csv') ? 'data-file' : 'text-file';
  } else if (meta.isArchive) {
    classification = 'archive';
    category = 'compressed-file';
  }

  // Additional classification based on filename patterns
  const lowerFileName = meta.fileName.toLowerCase();
  if (lowerFileName.includes('invoice')) {
    category = 'invoice';
    priority = 'high';
  } else if (lowerFileName.includes('contract')) {
    category = 'contract';
    priority = 'high';
  } else if (lowerFileName.includes('report')) {
    category = 'report';
    priority = 'medium';
  }

  items.push({
    json: {
      ...meta,
      classification: classification,
      category: category,
      priority: priority,
      processingStatus: 'classified'
    },
    binary: item.binary
  });
}

return items;
